contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: a candidate hash to lock, and amounts to send when locking and constructor funded
    function run(bytes32 h, uint lockAmount) public payable {
        require(lockAmount == 1 ether, "lock amount must be 1 ether");
        // Ensure this contract has enough balance to forward
        require(address(this).balance >= lockAmount);

        // Before: record contract and test balances
        uint beforeC = address(c).balance;
        uint beforeT = address(this).balance;

        // Attempt to lock a guess (should set guesses[msg.sender] on c if succeeds)
        bool lockedReverted;
        try c.lockInGuess{value: lockAmount}(h) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // Read c balance after lock attempt
        uint afterLockC = address(c).balance;
        uint afterLockT = address(this).balance;

        // Now attempt to settle. It may revert if no active guess or block conditions not met.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Read balances after settle
        uint afterSettleC = address(c).balance;
        uint afterSettleT = address(this).balance;

        // Observables: whether lock succeeded, whether settle reverted
        // General invariant to assert:
        // If lockInGuess reverted, c balance did not increase by lockAmount.
        // If lockInGuess succeeded, c balance increased by lockAmount.
        // If settle did not revert and it paid out, then this contract's balance increased by exactly 2 ether and c's balance decreased by exactly 2 ether.
        // If settle did not revert but did not pay out, then the locked slot was cleared (which we cannot directly read) but balances didn't transfer 2 ether.

        // We capture the payout detection by checking 2 ether transfer symmetric between c and this.
        bool payout_happened = (afterSettleT == afterLockT + 2 ether) && (afterSettleC + 2 ether == afterLockC);

        // Build assertion combining rules:
        // 1) lockInGuess success iff c balance increased by lockAmount.
        // 2) If settle succeeded and payout_happened then lock must have succeeded earlier.
        // 3) If lock failed then settle must not have produced a payout.
        assert( (lockedReverted == (afterLockC == beforeC))
             && ((!lockedReverted) == (afterLockC == beforeC + lockAmount))
             && (payout_happened == (!lockedReverted && !settleReverted))
             && (lockedReverted == true ? payout_happened == false : true)
        );
    }

    receive() external payable {}
}

