contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public property test:
    // We call settle (which may revert) and then observe two public facts:
    //  - address(c).balance (contract Ether balance)
    //  - the stored guess struct for this contract caller via the autogenerated getter
    // The invariant: if settle does not revert, then after the call the stored block for this caller must be zero;
    // additionally, if settle reverts then the contract balance must be unchanged; if settle succeeds then
    // the contract balance is either unchanged or decreased (payout), but in all cases the stored block is zero.
    // We express this as: either settle reverted and balance unchanged and stored block equals its before-value,
    // or settle succeeded and stored block == 0.

    function run() public payable {
        // no parameter preconditions
        // read before-values
        uint balBefore = address(c).balance;
        // read the stored guess struct for this caller (InvMutTest is msg.sender for calls)
        // autogenerated getter for mapping(address => guess) guesses is guesses(address) -> (uint, bytes32)
        (uint storedBlockBefore, bytes32 storedGuessBefore) = c.guesses(address(this));

        bool reverted;
        // call settle which may revert
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        (uint storedBlockAfter, bytes32 storedGuessAfter) = c.guesses(address(this));

        // General rule expressed in one assert:
        // - If the call reverted: contract balance must be unchanged and stored block must equal its previous value.
        // - If the call succeeded: stored block for this caller must be zero (cleared by settle); balance may be <= balBefore.
        assert(
            (reverted && balAfter == balBefore && storedBlockAfter == storedBlockBefore)
            || (!reverted && storedBlockAfter == 0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: the hash to lock, and the amount to send when calling lockInGuess
    function run(bytes32 h, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // read initial on-chain observable: contract balance
        uint256 beforeBalance = address(c).balance;

        // read current stored guess for this contract address (auto-generated getter).
        // Since C defines mapping(address => guess) guesses; the getter signature is guesses(address) -> (uint256, bytes32)
        (uint256 oldBlock, bytes32 oldHash) = c.guesses(address(this));

        bool reverted;
        // Try calling lockInGuess with provided amount; must be top-level call
        try c.lockInGuess{value: amount}(h) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state
        (uint256 newBlock, bytes32 newHash) = c.guesses(address(this));
        uint256 afterBalance = address(c).balance;

        // We assert a general rule covering both cases:
        // If there was no pending guess before (oldBlock == 0) and the caller sent exactly 1 ether,
        // then the call must succeed (not reverted), contract balance increases by 1 ether,
        // and the stored guess for this caller equals (block number recorded) newBlock == block.number + 1 and newHash == h.
        // Otherwise (oldBlock != 0 or amount != 1 ether) the call must revert and storage unchanged and balance unchanged.
        // Note: we cannot refer to the prior block number saved inside C, but the getter returns the recorded block number.

        assert(
            // Case A: allowed to lock
            ((oldBlock == 0 && amount == 1 ether && reverted == false && afterBalance == beforeBalance + 1 && newHash == h && newBlock == (block.number + 1))
            // Case B: must revert and state unchanged
            || ((oldBlock != 0 || amount != 1 ether) && reverted == true && newBlock == oldBlock && newHash == oldHash && afterBalance == beforeBalance))
        );
    }

    receive() external payable {}
}

