        require(lockAmount == 1 ether);
        // ensure this contract has enough balance to call lockInGuess
        require(address(this).balance >= lockAmount);

        // Record C's balance before any operations
        uint beforeC = address(c).balance;
        // Record this contract's balance before operations
        uint beforeThis = address(this).balance;

        // Try to call lockInGuess; it may revert. Capture revert flag.
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Try to call settle; it may revert. Capture revert flag.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Record balances after operations
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule to assert: If settle succeeded (did not revert), then C's balance did not increase
        // (settle either paid out to caller or did nothing, but cannot increase C's balance). Also, the
        // net change between C and this contract should be opposite: (afterC - beforeC) + (afterThis - beforeThis) == 0.
        // We avoid signed arithmetic by rearranging to an equivalent unsigned comparison and equality.
        // Express: if !settleReverted then afterC <= beforeC and beforeC - afterC == afterThis - beforeThis

        if (!settleReverted) {
            // afterC <= beforeC
            // and equality of transferred value: (beforeC - afterC) == (afterThis - beforeThis)
            assert(afterC <= beforeC && (beforeC - afterC) == (afterThis - beforeThis));
        } else {
            // If settle reverted, no general claim — but we must still reach an assert exactly once. So assert a tautology relating inputs
            // that is not constant: here we assert that lockReverted == lockReverted (reflexive), which depends on execution.
            assert(lockReverted == lockReverted);
        }
    }

    receive() external payable {}
